use crate::{model::*,unit_support::*,cq13 as c,rules::*};
fn clock(g:&mut Game){g.players[0].society_zone.card=Some(g.make_card("MSJZ03",0));}
fn drain(g:&mut Game){for _ in 0..120{if g.pending.is_some(){resolve_choice(g)}else if !g.stack.is_empty(){pass(g)}else{g.drive().unwrap();if g.pending.is_none()&&g.stack.is_empty(){return}}}panic!("CQ13 did not drain")}
#[test]fn cq13_original_definition_and_closed_catalog(){let d=crate::catalog::card(c::ID);assert_eq!(d.cost,7);assert_eq!(d.loyalty,vec!["红色";4]);assert_eq!(d.permanent_icons.investigation,2);assert_eq!(d.temporary_icons.influence,1);assert!(!d.supported);assert!(d.unique);assert_current_serial_catalog();assert_eq!(c::definition().abilities.len(),3);let mut a=c::definition().abilities[1].clone();a.costs.clear();assert!(crate::rules::validate_ability(c::ID,&a).is_err());assert!(crate::rules::validate_ability("JC125",&c::definition().abilities[2]).is_err());}
#[test]fn cq13_leave_is_forced_original_region_wave_with_restore(){let mut g=game();let id=field(&mut g,c::ID,0);let other=field(&mut g,"JC125",1);let hidden=field(&mut g,"JC125",2);g.board_mut(&hidden).unwrap().face_down=true;g.return_hand(&id);g.drive().unwrap();assert!(g.pending.is_none());assert_eq!(g.stack.len(),1);restore(&mut g);top(&mut g);assert!(g.board(&other).is_none()&&g.board(&hidden).is_none());assert!(g.players[0].hand.iter().any(|x|x.definition==c::ID));restore(&mut g);}
#[test]fn cq13_hidden_departure_does_not_trigger(){let mut g=game();let id=field(&mut g,c::ID,0);g.board_mut(&id).unwrap().face_down=true;let other=field(&mut g,"JC125",1);g.return_hand(&id);drain(&mut g);assert!(g.board(&other).is_some());}
#[test]fn cq13_entry_without_clock_has_no_optional_trigger(){let mut g=game();fund(&mut g,0,"JC049",7);let id=held(&mut g,c::ID,0);act(&mut g,0,Action{card_id:Some(id),region:Some(0),..Action::new("deploy")});top(&mut g);assert!(g.pending.is_none());assert!(!g.regions[0].destroyed);}
#[test]fn cq13_clock_optional_entry_modes_bind_original_region(){let mut g=game();clock(&mut g);fund(&mut g,0,"JC049",7);let id=held(&mut g,c::ID,0);act(&mut g,0,Action{card_id:Some(id),region:Some(0),..Action::new("deploy")});for _ in 0..10{if g.pending.is_some(){break}pass(&mut g);}assert!(g.pending.is_some());let p=g.pending.as_ref().unwrap();eprintln!("entry choice {} {:?}",p.choice.kind,p.choice.options.iter().map(|o|&o.id).collect::<Vec<_>>());choose(&mut g,vec!["destroy".into()]);choose(&mut g,vec!["region:1".into()]);top(&mut g);assert!(g.regions[1].destroyed);restore(&mut g);}
#[test]fn cq13_contest_paid_and_restorable(){let mut g=game();let id=field(&mut g,c::ID,0);fund(&mut g,0,"JC125",3);for s in 0..4{held(&mut g,if s==0{"BQ047"}else{"JC125"},s);}act(&mut g,0,Action{card_id:Some(id.clone()),ability_id:Some(c::CONTEST.into()),..Action::new("activate")});drain(&mut g);assert_eq!(g.mystic_history.len(),1);assert_eq!(g.mystic_history[0].winner_team,Some(g.team(0)));assert!(g.board(&id).is_none());assert!(g.players[0].graveyard.iter().any(|x|x.definition==c::ID));restore(&mut g);}
fn entry(g:&mut Game,mode:&str,r:usize){let id=field(g,c::ID,0);let source=g.source_snapshot(g.board(&id).unwrap().1,Some(0));g.emit_event(0,source,Event::Enter);g.drive().unwrap();choose(g,vec![mode.into()]);choose(g,vec![format!("region:{r}")]);}
#[test]fn cq13_destroyed_only_mode_target_change_and_cold_restore(){let mut g=game();clock(&mut g);g.regions[1].destroyed=true;entry(&mut g,"influence",1);let t=g.team(0);let n=g.regions[1].influence[t];restore(&mut g);top(&mut g);assert_eq!(g.regions[1].influence[t],n+1);let mut g=game();clock(&mut g);entry(&mut g,"destroy",1);g.regions[1].card=g.make_card("DQJC115",0);restore(&mut g);top(&mut g);assert!(!g.regions[1].destroyed);let mut g=game();clock(&mut g);g.regions[1].destroyed=true;entry(&mut g,"influence",1);g.regions[1].destroyed=false;restore(&mut g);top(&mut g);assert_eq!(g.regions[1].influence[g.team(0)],0);}
#[test]fn cq13_entry_clock_condition_rechecked_and_foreign_team_not_enough(){let mut g=game();g.players[2].society_zone.card=Some(g.make_card("MSJZ03",2));let id=field(&mut g,c::ID,0);let s=g.source_snapshot(g.board(&id).unwrap().1,Some(0));g.emit_event(0,s,Event::Enter);g.drive().unwrap();assert!(g.pending.is_none());clock(&mut g);entry(&mut g,"destroy",1);g.players[0].society_zone.card=Some(g.make_card("MSJC13",0));restore(&mut g);top(&mut g);assert!(!g.regions[1].destroyed);}
#[test]fn cq13_corrupt_and_duplicate_frames_reject_game_and_room(){let mut g=game();clock(&mut g);entry(&mut g,"destroy",1);for n in 0..5{let mut bad=g.clone();let f=bad.stack.last_mut().unwrap().frame.as_mut().unwrap();match n{0=>f.targets[0].region_instance=None,1=>f.source.card.definition="JC125".into(),2=>f.steps.clear(),3=>f.already_paid.push(PaidCost::Assets(vec![])),_=>bad.effects.push_back(Effect::Frame{frame:Box::new(f.clone())})}let json=serde_json::to_string(&bad).unwrap();assert!(Game::from_persisted(&json).is_err(),"variant {n}");let room=crate::room::RoomEnvelope::from_game(bad);assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).is_err());}}
#[test]fn cq13_original_leave_region_replacement_fizzles(){let mut g=game();let id=field(&mut g,c::ID,0);let other=field(&mut g,"JC125",1);g.return_hand(&id);g.drive().unwrap();g.regions[0].card=g.make_card("DQJC115",0);restore(&mut g);top(&mut g);assert!(g.board(&other).is_some());}

#[test]fn cq13_natural_clock_entry_contest_blink_export(){
 use crate::{deck,catalog,abi112_review_play_tests::Trace};
 fn start(seed:u64)->(Game,deck::DeckDraft){let mut d=deck::preset("watchers").unwrap();d.society_id=Some("MSCQ02".into());d.core_card_id=None;d.cards=vec![catalog::DeckEntry{card_id:"CQ13".into(),count:1},catalog::DeckEntry{card_id:"BQ047".into(),count:2},catalog::DeckEntry{card_id:"JZ42".into(),count:1},catalog::DeckEntry{card_id:"JC049".into(),count:3},catalog::DeckEntry{card_id:"JC042".into(),count:3},catalog::DeckEntry{card_id:"JC045".into(),count:3},catalog::DeckEntry{card_id:"JZ33".into(),count:3},catalog::DeckEntry{card_id:"JC043".into(),count:3},catalog::DeckEntry{card_id:"JC044".into(),count:3},catalog::DeckEntry{card_id:"JC046".into(),count:3},catalog::DeckEntry{card_id:"JC047".into(),count:3},catalog::DeckEntry{card_id:"JC048".into(),count:3},catalog::DeckEntry{card_id:"JC125".into(),count:19}];let mut cards=catalog::catalog().cards.clone();for c in &mut cards{if ["BQ047","JZ42","CQ13"].contains(&c.id.as_str()){c.supported=true;}}let mut ss=catalog::catalog().societies.clone();ss.iter_mut().find(|s|s.card.id=="MSCQ02").unwrap().card.supported=true;let d=deck::validate_with_registry(d,&cards,&ss).unwrap();let mut other=d.clone();other.society_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("doom".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d.clone(),other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();(g,d)}
 let(seed,g,d)=(1..8193).find_map(|seed|{let(g,d)=start(seed);let early=g.players[0].hand.iter().chain(g.players[0].deck.iter().take(7)).collect::<Vec<_>>();let bank=early.iter().filter(|c|catalog::card(&c.definition).color=="红"&&!matches!(c.definition.as_str(),"BQ047"|"JZ42"|"CQ13")).count();(early.iter().filter(|c|c.definition=="BQ047").count()==2&&early.iter().any(|c|c.definition=="CQ13")&&early.iter().any(|c|c.definition=="JZ42")&&bank>=5).then_some((seed,g,d))}).unwrap();let mut t=Trace::new_preserving_rng(g,"cq13-natural-clock-entry-blink".into(),7430);let mut before=0;let mut after=false;let mut generated=false;let mut marked=false;let mut convert_step=None;let mut clock_branch=false;
 for step in 0..2600{
  if step%100==0{eprintln!("doom natural step={step} turn={} assets={} red={} before={before} converted={} generated={generated} after={after} marked={marked}",t.room.game.turn,t.room.game.players[0].assets.len(),t.room.game.players[0].assets.iter().filter(|c|catalog::card(&c.definition).color=="红").count(),t.room.game.msjz03_active(0));}
  if let Some(p)=t.room.game.pending.clone(){if matches!(p.resolution,ChoiceResolution::Forecast{..}|ChoiceResolution::Frame{choice:FrameChoice::Forecast{..},..}){t.action(p.seat,Action{choice_id:Some(p.choice.id),top:Some(p.choice.options.iter().map(|o|o.id.clone()).collect()),bottom:Some(vec![]),..Action::new("choose")});continue}if p.choice.kind=="trigger"&&p.choice.options.iter().any(|o|o.id=="influence"){clock_branch=true;}let min=p.choice.min.unwrap_or(0);let mut opts=p.choice.options.clone();if p.choice.kind.contains("discard"){opts.sort_by_key(|o|t.room.game.players[p.seat].hand.iter().find(|c|c.id==o.id).map_or(0,|c|match c.definition.as_str(){"JC125"=>0,"BQ047"=>3,"CQ13"=>5,"JZ42"=>4,_=>1}));}let ids=if p.choice.kind=="trigger"{if p.choice.options.iter().any(|o|o.id=="influence"){vec!["influence".into()]}else if p.choice.options.iter().any(|o|o.id=="region:0"){vec!["region:0".into()]}else{p.choice.options.iter().filter(|o|o.id=="accept").map(|o|o.id.clone()).collect()}}else if p.choice.kind==crate::mystic_contest::COMMIT_KIND{opts.sort_by_key(|o|std::cmp::Reverse(o.card.as_ref().map_or(0,|c|c.cost.unwrap_or(0))));opts.iter().take(min).map(|o|o.id.clone()).collect()}else{opts.iter().take(min).map(|o|o.id.clone()).collect()};t.choose(ids);continue}
  if after&&generated&&t.room.game.mystic_contest.is_none()&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break}
  let g=&t.room.game;assert_eq!(g.status,"playing","natural ended at {step}");let legal=g.legal_actions(0);let card_is=|a:&&crate::model::LegalAction,id:&str|g.players[0].hand.iter().any(|c|Some(&c.id)==a.action.card_id.as_ref()&&c.definition==id);
  let wanted=if (g.players[0].assets.len()<7||!g.loyalty(0,"JZ42"))&&!g.msjz03_active(0){legal.iter().find(|a|a.action.kind=="asset"&&g.players[0].hand.iter().find(|c|Some(&c.id)==a.action.card_id.as_ref()).is_some_and(|c|if !g.loyalty(0,"JZ42"){catalog::card(&c.definition).color=="红"&&!matches!(c.definition.as_str(),"BQ047"|"JZ42"|"CQ13")}else{!matches!(c.definition.as_str(),"BQ047"|"JZ42"|"CQ13")}))}
   else if before<2{legal.iter().find(|a|a.action.kind=="deploy"&&a.action.region==Some(before)&&card_is(a,"BQ047"))}
   else if !g.msjz03_active(0){legal.iter().find(|a|a.action.kind=="play"&&card_is(a,"JZ42"))}
   else if !after{legal.iter().find(|a|a.action.kind=="deploy"&&a.action.region==Some(0)&&card_is(a,"CQ13"))}
   else if !generated{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(crate::cq13::CONTEST))}else{None};
  if let Some(a)=wanted{let a=a.action.clone();if a.kind=="deploy"{if before<2{before+=1}else{after=true}}if a.kind=="play"{convert_step=Some(step);}if a.ability_id.as_deref()==Some(crate::cq13::CONTEST){generated=true;}if a.ability_id.as_deref()==Some(crate::msjz03::ADD){marked=true;}t.action(0,a);}else{t.pass();}
 }
 assert!(before==2&&after&&generated&&clock_branch,"before={before} after={after} generated={generated} marked={marked} branch={clock_branch}");assert!(t.room.game.msjz03_active(0));assert!(t.room.game.mystic_history.iter().any(|o|o.ability_key==crate::cq13::CONTEST));assert!(t.room.game.regions[0].influence[t.room.game.team(0)]>0);
 let mut v=t.value();v["catalog"]=serde_json::to_value(catalog::catalog()).unwrap();v["sourceBindings"]=cq13_bindings();v["construction"]=serde_json::json!({"deck":d,"seed":seed,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true,"conversionDeclarationStep":convert_step});for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let duplicate=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(duplicate.state,s["expected"]["state"]);assert!(!duplicate.changed&&duplicate.journal.is_empty());s["duplicate"]=serde_json::to_value(duplicate).unwrap();}if let Ok(p)=std::env::var("CQ13_NATURAL_OUT"){std::fs::write(p,serde_json::to_vec(&v).unwrap()).unwrap();}
}

fn cq13_bindings()->serde_json::Value{use sha2::{Digest,Sha256};let mut b=crate::shoggoth_tests::shoggoth_source_bindings();for(n,s)in[("rust-game/src/cq13.rs",include_bytes!("cq13.rs").as_slice()),("rust-game/src/cq13_tests.rs",include_bytes!("cq13_tests.rs").as_slice()),("rust-game/src/attachment.rs",include_bytes!("attachment.rs").as_slice()),("rust-game/src/mystic_contest.rs",include_bytes!("mystic_contest.rs").as_slice()),("rust-game/src/pack_a_contest.rs",include_bytes!("pack_a_contest.rs").as_slice())]{b["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(s)));}b}

#[test]fn cq13_tie_does_not_blink_and_missing_source_not_chased(){let mut g=game();let id=field(&mut g,c::ID,0);fund(&mut g,0,"JC125",3);for s in 0..4{held(&mut g,"JC125",s);}act(&mut g,0,Action{card_id:Some(id.clone()),ability_id:Some(c::CONTEST.into()),..Action::new("activate")});drain(&mut g);assert_eq!(g.mystic_history[0].winner_team,None);assert!(g.board(&id).is_some());let mut g=game();let id=field(&mut g,c::ID,0);fund(&mut g,0,"JC125",3);for s in 0..4{held(&mut g,if s==0{"BQ047"}else{"JC125"},s);}act(&mut g,0,Action{card_id:Some(id.clone()),ability_id:Some(c::CONTEST.into()),..Action::new("activate")});g.return_hand(&id);drain(&mut g);assert!(g.players[0].hand.iter().any(|x|x.definition==c::ID));assert!(!g.regions.iter().flat_map(|r|&r.cards).any(|x|x.definition==c::ID));}
#[test]fn cq13_pending_tampering_and_missing_paid_play_frames_reject(){let mut g=game();clock(&mut g);let id=field(&mut g,c::ID,0);let s=g.source_snapshot(g.board(&id).unwrap().1,Some(0));g.emit_event(0,s,Event::Enter);g.drive().unwrap();for n in 0..3{let mut x=g.clone();let p=x.pending.as_mut().unwrap();match n{0=>p.seat=1,1=>p.choice.options.clear(),_=>p.choice.max=Some(2)}assert!(Game::from_persisted(&serde_json::to_string(&x).unwrap()).is_err());}let mut g=game();fund(&mut g,0,"JC049",7);let id=held(&mut g,c::ID,0);act(&mut g,0,Action{card_id:Some(id),region:Some(0),..Action::new("deploy")});let mut x=g.clone();x.stack.last_mut().unwrap().frame=None;assert!(Game::from_persisted(&serde_json::to_string(&x).unwrap()).is_err());let mut x=g.clone();x.stack.last_mut().unwrap().frame.as_mut().unwrap().source.card.definition="JC125".into();assert!(Game::from_persisted(&serde_json::to_string(&x).unwrap()).is_err());}
